/// `getNodeCommonData`
pub fn get_node_common_data(node: &Node) -> u32 {
    match node.kind {
        Kind::Block => {
            let n = node.as_block();
            (n.multi_line as u32) << 24
        }
        Kind::HeritageClause => {
            let n = node.as_heritage_clause();
            let token_idx = match n.token {
                Kind::ImplementsKeyword => 1,
                _ => 0,
            };
            token_idx << 24
        }
        Kind::ExportAssignment => {
            let n = node.as_export_assignment();
            (n.is_export_equals as u32) << 24
        }
        Kind::ExportSpecifier => {
            let n = node.as_export_specifier();
            (n.is_type_only as u32) << 24
        }
        Kind::PrefixUnaryExpression => {
            let n = node.as_prefix_unary_expression();
            let operator_idx = match n.operator {
                Kind::MinusToken => 1,
                Kind::TildeToken => 2,
                Kind::ExclamationToken => 3,
                Kind::PlusPlusToken => 4,
                Kind::MinusMinusToken => 5,
                _ => 0,
            };
            operator_idx << 24
        }
        Kind::PostfixUnaryExpression => {
            let n = node.as_postfix_unary_expression();
            let operator_idx = match n.operator {
                Kind::MinusMinusToken => 1,
                _ => 0,
            };
            operator_idx << 24
        }
        Kind::MetaProperty => {
            let n = node.as_meta_property();
            let keyword_token_idx = match n.keyword_token {
                Kind::NewKeyword => 1,
                _ => 0,
            };
            keyword_token_idx << 24
        }
        Kind::ArrayLiteralExpression => {
            let n = node.as_array_literal_expression();
            (n.multi_line as u32) << 24
        }
        Kind::ObjectLiteralExpression => {
            let n = node.as_object_literal_expression();
            (n.multi_line as u32) << 24
        }
        Kind::TypeOperator => {
            let n = node.as_type_operator_node();
            let operator_idx = match n.operator {
                Kind::ReadonlyKeyword => 1,
                Kind::UniqueKeyword => 2,
                _ => 0,
            };
            operator_idx << 24
        }
        Kind::ImportAttributes => {
            let n = node.as_import_attributes();
            let token_idx = match n.token {
                Kind::AssertKeyword => 1,
                _ => 0,
            };
            ((n.multi_line as u32) << 24) | (token_idx << 25)
        }
        Kind::SyntheticExpression => get_node_common_data_synthetic_expression(node),
        Kind::JsxText => {
            let n = node.as_jsx_text();
            (n.contains_only_trivia_white_spaces as u32) << 24
        }
        Kind::ModuleDeclaration => {
            let n = node.as_module_declaration();
            let keyword_idx = match n.keyword {
                Kind::NamespaceKeyword => 1,
                _ => 0,
            };
            keyword_idx << 24
        }
        Kind::ImportEqualsDeclaration => {
            let n = node.as_import_equals_declaration();
            (n.is_type_only as u32) << 24
        }
        Kind::ExportDeclaration => {
            let n = node.as_export_declaration();
            (n.is_type_only as u32) << 24
        }
        Kind::ImportType => {
            let n = node.as_import_type_node();
            (n.is_type_of as u32) << 24
        }
        Kind::ImportClause => {
            let n = node.as_import_clause();
            let phase_modifier_idx = match n.phase_modifier {
                Kind::TypeKeyword => 1,
                Kind::DeferKeyword => 2,
                Kind::SourceKeyword => 3,
                _ => 0,
            };
            phase_modifier_idx << 24
        }
        Kind::ImportSpecifier => {
            let n = node.as_import_specifier();
            (n.is_type_only as u32) << 24
        }
        Kind::JSDocTypeLiteral => {
            let n = node.as_js_doc_type_literal();
            (n.is_array_type as u32) << 24
        }
        Kind::JSDocParameterTag | Kind::JSDocPropertyTag => {
            let n = node.as_js_doc_parameter_or_property_tag();
            ((n.is_bracketed as u32) << 24) | ((n.is_name_first as u32) << 25)
        }
        _ => 0,
    }
}

/// `recordNodeStrings`
pub fn record_node_strings(node: &Node, strs: &mut StringTable, nodes: &[Node]) -> u32 {
    match node.kind {
        Kind::Identifier => strs.add(
            nodes,
            node.as_identifier().text.as_bytes(),
            node.kind,
            node.pos(),
            node.end(),
        ),
        Kind::PrivateIdentifier => strs.add(
            nodes,
            node.as_private_identifier().text.as_bytes(),
            node.kind,
            node.pos(),
            node.end(),
        ),
        Kind::JsxText => strs.add(
            nodes,
            node.as_jsx_text().literal_like_node_base.text.as_bytes(),
            node.kind,
            node.pos(),
            node.end(),
        ),
        Kind::JSDocText => strs.add(
            nodes,
            node.as_js_doc_text()
                .js_doc_comment_base
                .text
                .join("")
                .as_bytes(),
            node.kind,
            node.pos(),
            node.end(),
        ),
        Kind::JSDocLink => strs.add(
            nodes,
            node.as_js_doc_link()
                .js_doc_comment_base
                .text
                .join("")
                .as_bytes(),
            node.kind,
            node.pos(),
            node.end(),
        ),
        Kind::JSDocLinkPlain => strs.add(
            nodes,
            node.as_js_doc_link_plain()
                .js_doc_comment_base
                .text
                .join("")
                .as_bytes(),
            node.kind,
            node.pos(),
            node.end(),
        ),
        Kind::JSDocLinkCode => strs.add(
            nodes,
            node.as_js_doc_link_code()
                .js_doc_comment_base
                .text
                .join("")
                .as_bytes(),
            node.kind,
            node.pos(),
            node.end(),
        ),
        _ => panic!("Unexpected node kind {:?}", node.kind),
    }
}

/// `recordExtendedData` — returns the byte offset of the node's extended data.
pub fn record_extended_data(node: &Node, st: &mut EncSt, nodes: &[Node]) -> u32 {
    let offset = st.extended_data.len() as u32;
    match node.kind {
        Kind::StringLiteral => record_extended_data_string_literal(node, st, nodes),
        Kind::NumericLiteral => record_extended_data_numeric_literal(node, st, nodes),
        Kind::BigIntLiteral => record_extended_data_big_int_literal(node, st, nodes),
        Kind::RegularExpressionLiteral => {
            record_extended_data_regular_expression_literal(node, st, nodes)
        }
        Kind::NoSubstitutionTemplateLiteral => {
            record_extended_data_no_substitution_template_literal(node, st, nodes)
        }
        Kind::TemplateHead => record_extended_data_template_head(node, st, nodes),
        Kind::TemplateMiddle => record_extended_data_template_middle(node, st, nodes),
        Kind::TemplateTail => record_extended_data_template_tail(node, st, nodes),
        Kind::SourceFile => record_extended_data_source_file(node, st, nodes),
        _ => panic!("unknown extended data node kind {:?}", node.kind),
    }
    offset
}
